buggy:
int sum_to(int n) {
    int s = 0;
    for (int i = 1; i < n; ++i) s += i;
    return s;
}

fixed:
int sum_to(int n) {
    int s = 0;
    for (int i = 1; i <= n; ++i) s += i;
    return s;
}

